const XMLHttpRequest=require("xmlhttprequest").XMLHttpRequest,API="https://api.escuelajs.co/api/v1";function fetchData(e,t){let o=new XMLHttpRequest;o.open("GET",e,!0),o.onreadystatechange=function(r){if(4===o.readyState){if(200!==o.status){const o=new Error("Error"+e);return t(o,null)}t(null,JSON.parse(o.responseText))}},o.send()}fetchData(`${API}/products`,(function(e,t){if(e)return console.error(e);fetchData(`${API}/products/${t[0].id}`,(function(e,o){if(e)return console.error(e);fetchData(`${API}/categories/${o?.category.id}`,(function(e,r){if(e)return console.error(e);console.log(t[0]),console.log(o.title),console.log(r.name)}))}))}));